562	IRAM_ATTR void *riscv_dispatch_irq(uintreg_t mcause, uintreg_t *regs)
563	{
564	  int irq;
565	  bool is_irq = (RISCV_IRQ_BIT & mcause) != 0;
566	  bool is_edge = false;
567	  int cpu = this_cpu();
568	
569	  if (is_irq)
570	    {
571	      uint8_t cpuint = (mcause & VECTORS_MCAUSE_REASON_MASK) -
572	                       RV_EXTERNAL_INT_OFFSET;
573	
574	      DEBUGASSERT(cpuint >= 0 && cpuint < ESP_NCPUINTS);
575	
576	      irq = esp_cpuint_to_irq(cpuint, cpu);
577	
578	      if (irq < 0)
579	        {
580	          /* No handle in NuttX's g_handle_map.  Interrupts allocated
581	           * through ESP-HAL's esp_intr_alloc_* (jpeg, dma2d) register
582	           * their handler in the ESP-HAL table (s_intr_handlers,
583	           * riscv/interrupt.c) instead of g_handle_map.  Call that
584	           * handler directly -- its ISR clears the level source, so
585	           * skipping it would leave the line asserted forever and
586	           * re-trigger this dispatch (level-triggered storm).
587	           */
588	
589	          intr_handler_t hal_handler = intr_handler_get(cpuint);
590	          if (hal_handler != NULL)
591	            {
592	              (*hal_handler)(intr_handler_get_arg(cpuint));
593	              return regs;
594	            }
595	
596	          irqwarn("No IRQ found for cpuint=%d cpu=%d\n", cpuint, cpu);
597	          return regs;
598	        }
599	
600	#ifdef CONFIG_ESPRESSIF_IRAM_ISR_DEBUG
601	      /* Check if non-IRAM interrupts are disabled */
602	
603	      if (esp_intr_noniram_is_disabled(cpu))
604	        {
605	          /* Sum-up the IRAM-enabled counter associated with the IRQ */
606	
607	          esp_irq_iram_interrupt_record(irq, this_cpu());
608	        }
609	#endif
610	
611	      is_edge = esprv_int_get_type(cpuint) != INTR_TYPE_LEVEL;
612	      if (is_edge)
613	        {
614	          /* Clear edge interrupts. */
615	
616	          esp_cpu_intr_edge_ack(cpuint);
617	        }
618	    }
619	  else
620	    {
621	      /* It's exception */
